import React, { useId } from 'react';

/**
 * JenesisLogo — the JENESIS mark: a J (a stem with a hook sweeping to the
 * lower left) inside a rounded-square badge.
 *
 * The geometry below is generated by .merge-work/make_logo.py, the same script
 * that renders build/icon*.ico, the favicons and the installer graphics, so the
 * logo in the interface and the logo on the Windows shortcut are the same
 * shape. There is no G anywhere in this file: the mark is a J, and
 * tests/branding-consistency.test.js asserts it.
 *
 * The colour follows the application: red for Seller, green for Maintenance,
 * blue for Admin — and it does not change between Light and Dark Mode.
 */

export const JENESIS_MARK_PATH = 'M 42.00 16.00 L 42.00 40.00 A 13.50 13.50 0 0 1 22.16 51.92';
export const JENESIS_BADGE_PATH =
  'M 18.00 3.00 H 46.00 A 15.00 15.00 0 0 1 61.00 18.00 V 46.00 A 15.00 15.00 0 0 1 46.00 61.00 ' +
  'H 18.00 A 15.00 15.00 0 0 1 3.00 46.00 V 18.00 A 15.00 15.00 0 0 1 18.00 3.00 Z';

/** Badge gradients — one per application identity (light → deep). */
const TONES = {
  brand: ['#1d4ed8', '#0b1f4b'],
  seller: ['#dc2626', '#450a0a'],
  maintenance: ['#16a34a', '#052e16'],
  admin: ['#2563eb', '#0b1f4b']
};

/**
 * @param {object}  props
 * @param {string}  props.tone        'seller' | 'maintenance' | 'admin' | 'brand'
 * @param {number}  props.size        edge length in pixels (the mark is square)
 * @param {boolean} props.wordmark    draw the JENESIS wordmark next to the mark
 * @param {string}  props.className   extra classes (spacing, alignment)
 * @param {string}  props.label       accessible name; defaults to "JENESIS"
 */
export default function JenesisLogo({
  tone = 'brand',
  size = 32,
  wordmark = false,
  className = '',
  label = 'JENESIS',
  title
}) {
  const gradientId = `jenesis-mark-${useId().replace(/[:]/g, '')}`;
  const [top, bottom] = TONES[tone] || TONES.brand;

  return (
    <span className={`inline-flex items-center ${wordmark ? 'space-x-2.5' : ''} ${className}`}>
      <svg
        width={size}
        height={size}
        viewBox="0 0 64 64"
        role="img"
        aria-label={label}
        className="shrink-0"
        data-jenesis-mark={tone}
      >
        <title>{title || label}</title>
        <defs>
          <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor={top} />
            <stop offset="1" stopColor={bottom} />
          </linearGradient>
        </defs>
        <path d={JENESIS_BADGE_PATH} fill={`url(#${gradientId})`} />
        <path
          d={JENESIS_MARK_PATH}
          fill="none"
          stroke="#ffffff"
          strokeWidth="7.5"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
      {wordmark && (
        <span
          className="font-extrabold tracking-wide leading-none"
          style={{ fontSize: Math.max(12, Math.round(size * 0.44)), color: 'rgb(var(--j-accent-text))' }}
        >
          {label}
        </span>
      )}
    </span>
  );
}
